const languageSwitcher = document.querySelector("#language-switcher");
const supportedLanguages = Object.keys(translations);
const originalTitle = document.title;
const originalContent = new WeakMap();
document.querySelectorAll("[data-i18n]").forEach((element) => {
  originalContent.set(element, element.innerHTML);
});
const storedLanguage = localStorage.getItem("old-launchpad-language");
const browserLanguage = navigator.language.slice(0, 2).toLowerCase();
let activeLanguage = supportedLanguages.includes(storedLanguage)
  ? storedLanguage
  : supportedLanguages.includes(browserLanguage) ? browserLanguage : "de";

function applyLanguage(language = activeLanguage) {
  activeLanguage = supportedLanguages.includes(language) ? language : "de";
  const dictionary = translations[activeLanguage];
  const legalDictionary = legalTranslations[activeLanguage] ?? {};
  document.documentElement.lang = activeLanguage;
  const titleKey = document.querySelector("title")?.dataset.i18n;
  const translatedTitle = titleKey && (dictionary[titleKey] ?? legalDictionary[titleKey]);
  if (translatedTitle) document.title = translatedTitle;
  else if (!titleKey) document.title = dictionary.metaTitle;
  else document.title = originalTitle;
  const description = document.querySelector('meta[name="description"]');
  if (description) description.content = dictionary.metaDescription;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    const translation = dictionary[key] ?? legalDictionary[key];
    element.innerHTML = translation ?? originalContent.get(element);
  });

  document.querySelectorAll("[data-i18n-attr]").forEach((element) => {
    const [attribute, key] = element.dataset.i18nAttr.split(":");
    const translation = dictionary[key] ?? legalDictionary[key];
    if (translation !== undefined) element.setAttribute(attribute, translation);
  });

  document.querySelectorAll('.translation-notice').forEach((element) => {
    element.hidden = activeLanguage === 'de';
  });
  if (languageSwitcher) languageSwitcher.value = activeLanguage;
}

languageSwitcher?.addEventListener("change", () => {
  localStorage.setItem("old-launchpad-language", languageSwitcher.value);
  applyLanguage(languageSwitcher.value);
});

window.applyOldLaunchpadLanguage = applyLanguage;
applyLanguage();
